import{_ as o,o as d,c as a,a5 as c}from"./chunks/framework.D47SInms.js";const t="/RBQ/nightly/images/app/home-sound.pc.ko.png",r="/RBQ/nightly/images/app/media-audio.pc.ko.png",i="/RBQ/nightly/images/app/media-sound.pc.ko.png",_=JSON.parse('{"title":"미디어","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/gui/media.md","filePath":"ko/manual/gui/media.md","lastUpdated":1791600043000}'),l={name:"ko/manual/gui/media.md"};function n(h,e,p,s,m,u){return d(),a("div",null,[...e[0]||(e[0]=[c('<h1 id="미디어" tabindex="-1">미디어 <a class="header-anchor" href="#미디어" aria-label="Permalink to &quot;미디어&quot;">​</a></h1><p>로봇 카메라로 사진을 찍고 영상을 녹화하고, 소리를 녹음하거나 로봇 스피커로 틀 수 있습니다. 파일은 모두 로봇에 저장되고, 앱은 그 목록을 보여 주고 재생하거나 내려받습니다.</p><h2 id="control-home" tabindex="-1">제어 홈에서 <a class="header-anchor" href="#control-home" aria-label="Permalink to &quot;제어 홈에서 {#control-home}&quot;">​</a></h2><p>제어 홈 오른쪽 아래 <code>워키토키</code> 버튼 왼쪽에 버튼 두 개가 있습니다. 화면이 좁으면 <code>워키토키</code> 위로 세로로 쌓입니다.</p><table tabindex="0"><thead><tr><th>버튼</th><th>하는 일</th></tr></thead><tbody><tr><td><code>사운드</code></td><td>소리 목록을 엽니다. 하나를 탭하면 로봇에서 <strong>반복 재생</strong>하고, 같은 것을 다시 탭하거나 <code>정지</code>를 탭하면 멈춥니다. 재생 중에는 버튼에 초록 점이 붙습니다. 앱 연결이 모두 끊기거나 30분이 지나면 로봇이 스스로 멈춥니다.</td></tr><tr><td><code>촬영</code></td><td><code>사진</code>과 <code>녹화</code> 중 하나를 고르는 창을 엽니다. <code>사진</code>은 로봇 전방·후방 카메라 사진을 저장하고, <code>녹화</code>는 영상 녹화를 시작합니다. 녹화 중에는 버튼이 빨갛게 바뀌고 경과 시간이 표시되며, 누르면 저장합니다.</td></tr></tbody></table><p>사진과 녹화 결과는 화면 아래 알림으로 알려 줍니다.</p><p><img src="'+t+'" alt="사운드 팝오버"></p><p><code>사운드</code> 목록에는 내장 소리, 내가 올린 소리(<code>내 사운드</code>), 최근 녹음 여덟 개(<code>최근 녹음</code>)가 나옵니다. 전체 목록은 오른쪽 위 <code>목록</code>을 탭해 미디어 화면에서 봅니다.</p><h2 id="미디어-화면-열기" tabindex="-1">미디어 화면 열기 <a class="header-anchor" href="#미디어-화면-열기" aria-label="Permalink to &quot;미디어 화면 열기&quot;">​</a></h2><p>허브의 <code>미디어</code> 타일을 탭합니다. 로봇이 연결된 동안에만 열립니다. 왼쪽 목록에서 <code>사진</code>·<code>녹화</code>·<code>블랙박스</code>·<code>녹음</code>·<code>사운드</code>를 고릅니다. 폰처럼 좁은 화면에서는 이 목록이 위쪽 탭으로 바뀝니다. 녹음이나 녹화가 진행 중이면 해당 항목에 빨간 점이 붙습니다.</p><h2 id="사진" tabindex="-1">사진 <a class="header-anchor" href="#사진" aria-label="Permalink to &quot;사진&quot;">​</a></h2><p><code>사진 찍기</code>를 탭하면 전방·후방 카메라 사진이 함께 저장됩니다. 한 번 찍은 것이 카드 하나로 묶이고, 날짜별로 최신 것이 위에 옵니다. 카드를 탭하면 크게 보고 <code>내려받기</code>로 이 기기에 저장할 수 있습니다.</p><h2 id="녹화" tabindex="-1">녹화 <a class="header-anchor" href="#녹화" aria-label="Permalink to &quot;녹화&quot;">​</a></h2><p><code>녹화 시작</code>을 탭하면 전방·후방 카메라를 함께 녹화합니다. 초당 10장이고 한 번에 최대 30분입니다. 다시 탭하면 저장되며, 전방·후방이 각각 한 파일로 남습니다. 제어 홈 <code>촬영</code>의 <code>녹화</code>와 같은 기능입니다.</p><p>목록에서는 한 번 녹화한 전방·후방이 한 줄로 묶입니다. <code>전방</code>이나 <code>후방</code>을 탭해 보고, 보는 중에도 위쪽에서 카메라를 바꿀 수 있습니다. 내려받기는 두 파일을 함께 받습니다.</p><h2 id="블랙박스" tabindex="-1">블랙박스 <a class="header-anchor" href="#블랙박스" aria-label="Permalink to &quot;블랙박스&quot;">​</a></h2><p>로봇이 스스로 계속 녹화한 영상입니다. 30분 단위로 나뉘어 저장됩니다. 탭해서 재생하거나 내려받습니다.</p><h2 id="recording" tabindex="-1">녹음 <a class="header-anchor" href="#recording" aria-label="Permalink to &quot;녹음 {#recording}&quot;">​</a></h2><p>녹음은 두 가지입니다. 녹음을 시작하기 전에 고릅니다.</p><table tabindex="0"><thead><tr><th>선택</th><th>담기는 소리</th></tr></thead><tbody><tr><td><code>내 마이크</code></td><td>녹음하는 동안 <code>워키토키</code>를 누르고 말한 소리. 안내 방송처럼 미리 녹음해 두고 로봇 스피커로 반복해 틀 수 있습니다.</td></tr><tr><td><code>로봇 마이크</code></td><td>로봇 마이크에 들리는 소리.</td></tr></tbody></table><p>로봇에 마이크 장치가 없으면 선택지가 나오지 않고 <code>내 마이크</code>로만 녹음합니다. 로봇은 켜질 때와 오디오 화면을 보는 동안 1분마다 마이크 입력을 잠깐 들어 봅니다. 소리가 거의 들어오지 않으면 <code>로봇 마이크에 소리가 거의 들어오지 않습니다 — 마이크가 꽂혀 있는지 확인하세요</code>가 뜹니다. 안내일 뿐이고, 듣기와 녹음은 그대로 쓸 수 있습니다.</p><p>녹음을 멈췄는데 소리가 거의 없었으면 안내가 뜹니다. <code>로봇 마이크</code>라면 <code>방금 녹음에 소리가 거의 없습니다 — 로봇에 마이크가 꽂혀 있는지 확인하세요</code>가 나옵니다. 로봇의 오디오 보드는 마이크가 꽂혀 있지 않아도 녹음이 되는 것처럼 보이므로, 이 안내로 확인합니다. <code>내 마이크</code>라면 녹음하는 동안 <code>워키토키</code>를 누르고 말했는지 확인하세요.</p><p><img src="'+r+'" alt="녹음"></p><p>녹음 목록에서 <code>로봇에서 재생</code>을 탭하면 로봇 스피커로 틉니다. <code>반복 재생</code>을 켜 두면 정지할 때까지 되풀이합니다. 녹음은 오디오 팝오버에서도 시작할 수 있습니다(<a href="/RBQ/nightly/ko/manual/gui/audio.html#recording">오디오</a>).</p><h2 id="delete" tabindex="-1">지우기 <a class="header-anchor" href="#delete" aria-label="Permalink to &quot;지우기 {#delete}&quot;">​</a></h2><p><code>사진</code>·<code>녹화</code>·<code>블랙박스</code>·<code>녹음</code>과 <code>내 사운드</code>에서 파일을 로봇에서 지울 수 있습니다. 섹션 오른쪽 위의 휴지통(<code>파일 지우기</code>)을 탭하면 선택 모드가 됩니다. 지울 항목을 탭해 고른 뒤 <code>삭제</code>를 탭하고, 확인 창에서 한 번 더 <code>삭제</code>를 탭합니다. 모두 지우려면 <code>전체 선택</code> 뒤 <code>삭제</code>를 탭합니다. <code>취소</code>를 탭하면 선택 모드를 끝냅니다.</p><p>사진과 녹화는 전방·후방이 한 항목이라 함께 지워집니다. 지금 녹화·녹음 중인 파일은 지워지지 않고, 몇 개를 건너뛰었는지 알려 줍니다. 지운 파일은 되살릴 수 없습니다.</p><h2 id="사운드" tabindex="-1">사운드 <a class="header-anchor" href="#사운드" aria-label="Permalink to &quot;사운드&quot;">​</a></h2><p><img src="'+i+'" alt="사운드"></p><p>경보·사이렌, 알림·차임, 동물, 기타로 묶인 내장 소리입니다. 탭하면 로봇에서 재생합니다. 처음 트는 소리는 로봇으로 먼저 올린 뒤 재생하므로 잠깐 기다립니다. <code>반복 재생</code>을 켜 두면 정지할 때까지 되풀이합니다.</p><p><code>내 사운드</code>의 <code>파일 올리기</code>로 이 기기에 있는 소리 파일(mp3·wav 등, 10 MB 이하)을 로봇에 올려 두면 언제든 재생할 수 있습니다.</p><p>소리가 나가는 곳은 오디오와 같습니다. PTZ 카메라가 달려 있으면 PTZ 스피커로 나갑니다(<a href="/RBQ/nightly/ko/manual/gui/audio.html#output">소리가 나가는 곳</a>).</p>',32)])])}const g=o(l,[["render",n]]);export{_ as __pageData,g as default};
